// Regenerates every TEXT artifact derived from branding/pengu.svg: the rounded and
// frameless SVG variants and the Android adaptive-icon XML. The geometry is read
// from the master, so the paths are never typed twice.
//
//   node scripts/gen_brand_icons.mjs
//
// Edit `branding/pengu.svg` and re-run this; never edit the generated files. The
// rasters are committed outputs: rebuild them with scripts/gen_brand_rasters.mjs.

import { readFileSync, writeFileSync } from "node:fs";

const MASTER = "branding/pengu.svg";
const RES = "app/androidApp/src/main/res";
const SCALE = 1.78; // the frameless variant: mark at ~85 % of the canvas
const master = readFileSync(MASTER, "utf8");

const grab = (re, what) => {
  const m = re.exec(master);
  if (!m) throw new Error(`${MASTER}: ${what} not found`);
  return m;
};

const fillOf = (id) =>
  new RegExp(`<use href="#${id}" fill="(#[0-9A-Fa-f]{6})"`).exec(master)?.[1] ?? null;

// ---- geometry: one source ----------------------------------------------------
// `<path id="beak…">` draws the mark's outline: its stroke is the corner radius and
// it decides the hull. `<path id="jaw…">` is a tone drawn inside that outline as exact
// geometry (stroke-width 0), so it needs neither a gradient nor a mask.
const readPaths = (prefix) =>
  [...master.matchAll(new RegExp(`<path id="(${prefix}[A-Za-z]*)" d="([^"]+)" stroke-width="([^"]+)"`, "g"))].map(
    ([, id, d, stroke]) => ({
      id,
      d,
      stroke: Number(stroke),
      pts: [...d.matchAll(/(-?[\d.]+)[ ,](-?[\d.]+)/g)].map((m) => [Number(m[1]), Number(m[2])]),
      color: fillOf(id),
    }),
  );
const shapes = readPaths("beak");
const details = readPaths("jaw");
if (!shapes.length) throw new Error(`${MASTER}: no <path id="beak…"> found`);
if (!shapes[0].color) throw new Error(`${MASTER}: <path id="${shapes[0].id}"> has no fill`);
for (const d of details) if (!d.color) throw new Error(`${MASTER}: <path id="${d.id}"> has no fill on its <use>`);

const tile = grab(/<rect width="1024" height="1024" fill="(#[0-9A-Fa-f]+)"\/>/, "tile rect")[1];

const header = (what) =>
  `<!-- Generated by scripts/gen_brand_icons.mjs from ${MASTER} — ${what}.\n` +
  `     Edit the master and re-run the script; this file is overwritten. -->`;

const svgPath = (p, fill) =>
  p.stroke
    ? `<path d="${p.d}" fill="${fill}" stroke="${fill}" stroke-width="${p.stroke}" stroke-linejoin="round"/>`
    : `<path d="${p.d}" fill="${fill}"/>`;

// ---- 1. rounded: same art, 22 % corners, transparent outside the tile --------
writeFileSync(
  "branding/pengu-rounded.svg",
  master
    .replace(`<rect width="1024" height="1024" fill="${tile}"/>`, `<rect width="1024" height="1024" rx="224" fill="${tile}"/>`)
    .replace("<svg ", `${header("the 22 % corner-radius variant")}\n<svg `),
);

// ---- 2. frameless: no tile, bigger mark, one-device-pixel outline -----------
const frameless = (size) => {
  const w = 1024 / size / SCALE; // one device pixel, in user units
  return `${header(`the frameless variant, outline of one device pixel at ${size} px`)}
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1024 1024" width="512" height="512" role="img" aria-labelledby="t">
  <title id="t">Pengu</title>
  <desc id="d">A play button shaped like a beak, its jaws split by a fold.</desc>
  <defs>
${shapes.map((s) => `    <path id="${s.id}" d="${s.d}" stroke-width="${s.stroke}" stroke-linejoin="round"/>`).join("\n")}
  </defs>

  <g transform="translate(502 512) scale(${SCALE}) translate(-512 -512)">
${shapes
  .map(
    (s) => `    <path d="${s.d}" fill="${tile}" stroke="${tile}" stroke-width="${(s.stroke + 2 * w).toFixed(1)}"
          stroke-linejoin="round"/>`,
  )
  .join("\n")}
${shapes.map((s) => `    ${svgPath(s, s.color)}`).join("\n")}
${details.map((d) => `    ${svgPath(d, d.color)}`).join("\n")}
  </g>
</svg>
`;
};
writeFileSync("branding/pengu-frameless.svg", frameless(256));

// ---- 3. Android adaptive icon ----------------------------------------------
// Fitted, never typed: a hand-set scale silently tells the truth about whatever
// artwork it was tuned for, and this one was tuned for the penguin drawing that
// used to fill the 1024 canvas. The mark now fills a fixed share of the 72 dp mask
// (see ANDROID_MARK_FILL) and the fit is checked against the 66 dp safe circle.
const MAX_SAFE_RADIUS_DP = 33;
const hull = shapes.reduce(
  (acc, s) => {
    const half = s.stroke / 2;
    const xs = s.pts.map(([x]) => x), ys = s.pts.map(([, y]) => y);
    return {
      x0: Math.min(acc.x0, Math.min(...xs) - half),
      x1: Math.max(acc.x1, Math.max(...xs) + half),
      y0: Math.min(acc.y0, Math.min(...ys) - half),
      y1: Math.max(acc.y1, Math.max(...ys) + half),
    };
  },
  { x0: Infinity, x1: -Infinity, y0: Infinity, y1: -Infinity },
);
const hullCx = (hull.x0 + hull.x1) / 2;
const hullCy = (hull.y0 + hull.y1) / 2;
const hullSpan = Math.max(hull.x1 - hull.x0, hull.y1 - hull.y0);
// Less than the rasters' 72 %: the launcher crops the 108 dp canvas to a 72 dp mask
// and scales that up, so the same fill reads bigger than the square tile next to
// other apps' icons. 60 % matches their visual weight.
const ANDROID_MARK_FILL = 0.6;
const androidScale = (ANDROID_MARK_FILL * 72) / hullSpan;
const cornerDp =
  Math.max(...shapes.map((s) => Math.max(...s.pts.map(([x, y]) => Math.hypot(x - hullCx, y - hullCy))) + s.stroke / 2)) *
  androidScale;
if (cornerDp > MAX_SAFE_RADIUS_DP)
  throw new Error(`${MASTER}: corners reach ${cornerDp.toFixed(1)} dp, outside the ${MAX_SAFE_RADIUS_DP} dp safe circle`);

const androidPath = (p, color, indent) => `${indent}<path
${indent}    android:pathData="${p.d}"
${indent}    android:strokeColor="${color}"
${indent}    android:strokeWidth="${p.stroke}"
${indent}    android:strokeLineJoin="round"
${indent}    android:fillColor="${color}" />`;

// The mark first, then the jaw on top: both are exact paths, so the tone boundary
// needs no clip and the icon renders the same as the master.
const androidLayers = [...shapes, ...details].map((p) => androidPath(p, p.color, "            ")).join("\n");

writeFileSync(
  `${RES}/drawable/ic_launcher_background.xml`,
  `<?xml version="1.0" encoding="utf-8"?>
${header("the adaptive-icon background")}
<vector xmlns:android="http://schemas.android.com/apk/res/android"
    android:width="108dp"
    android:height="108dp"
    android:viewportWidth="108"
    android:viewportHeight="108">
    <path android:pathData="M0,0h108v108h-108z" android:fillColor="${tile}" />
</vector>
`,
);

writeFileSync(
  `${RES}/drawable-v24/ic_launcher_foreground.xml`,
  `<?xml version="1.0" encoding="utf-8"?>
${header("the adaptive-icon foreground")}
<!-- Fitted from the master, not typed: the hull fills ${(ANDROID_MARK_FILL * 100).toFixed(0)} % of the 72 dp mask
     (${(hullSpan * androidScale).toFixed(1)} dp across, corners at ${cornerDp.toFixed(1)} dp, inside the 66 dp safe circle)
     and is centred on the hull. Flat tones on exact paths: no gradients and no clips. -->
<vector xmlns:android="http://schemas.android.com/apk/res/android"
    android:width="108dp"
    android:height="108dp"
    android:viewportWidth="108"
    android:viewportHeight="108">
    <group
        android:translateX="54"
        android:translateY="54"
        android:scaleX="${androidScale.toFixed(5)}"
        android:scaleY="${androidScale.toFixed(5)}">
        <group android:translateX="${-hullCx}" android:translateY="${-hullCy}">
${androidLayers}
        </group>
    </group>
</vector>
`,
);

// Themed icons (Android 13+) need a monochrome layer: one flat silhouette the
// system tints. Without it the launcher has nothing to draw in theme mode.
writeFileSync(
  `${RES}/drawable/ic_launcher_monochrome.xml`,
  `<?xml version="1.0" encoding="utf-8"?>
${header("the adaptive-icon monochrome layer")}
<!-- Same fit as the foreground, flattened to one colour: the system tints this layer,
     so only the silhouette matters and the jaw adds nothing. -->
<vector xmlns:android="http://schemas.android.com/apk/res/android"
    android:width="108dp"
    android:height="108dp"
    android:viewportWidth="108"
    android:viewportHeight="108">
    <group
        android:translateX="54"
        android:translateY="54"
        android:scaleX="${androidScale.toFixed(5)}"
        android:scaleY="${androidScale.toFixed(5)}">
        <group android:translateX="${-hullCx}" android:translateY="${-hullCy}">
${shapes.map((s) => androidPath(s, "#FFFFFF", "            ")).join("\n")}
        </group>
    </group>
</vector>
`,
);

console.log("wrote branding/pengu-rounded.svg");
console.log("wrote branding/pengu-frameless.svg");
console.log(`wrote ${RES}/drawable/ic_launcher_background.xml`);
console.log(`wrote ${RES}/drawable-v24/ic_launcher_foreground.xml`);
console.log(`wrote ${RES}/drawable/ic_launcher_monochrome.xml`);
console.log(`
Rasters are committed outputs; rebuild them with:

  npm i --no-save sharp && node scripts/gen_brand_rasters.mjs`);
